var response = await client.ShoppingCart.GetShoppingCartAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var shoppingCart = (IReadOnlyDictionary<string, object?>)body["shopping_cart"]!;
var cartPage = (IReadOnlyDictionary<string, object?>)shoppingCart["cart_page"]!;
Console.WriteLine(cartPage["show_product_thumbnail"]);

patch_shopping_cart.code:
var response = await client.ShoppingCart.PatchShoppingCartAsync(new Dictionary<string, object?>
{
    ["shopping_cart"] = new Dictionary<string, object?>
    {
        ["cart_page"] = new Dictionary<string, object?> { ["show_product_thumbnail"] = true },
        ["flying_cart"] = new Dictionary<string, object?> { ["save_cart"] = true },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var shoppingCart = (IReadOnlyDictionary<string, object?>)body["shopping_cart"]!;
var flyingCart = (IReadOnlyDictionary<string, object?>)shoppingCart["flying_cart"]!;
Console.WriteLine(flyingCart["save_cart"]);

